"""SQL · referencia completa (etapas 6 y 7). Los ejemplos corren en SQLite dentro de Aprende."""
from .tabla import filas

_T = "CREATE TABLE ventas (id INTEGER, ciudad TEXT, total REAL, fecha TEXT);⏎INSERT INTO ventas VALUES (1,'Bogotá',100,'2026-01-05'),(2,'Cali',80,'2026-01-09'),(3,'Bogotá',50,'2026-02-01');⏎"

E6 = filas(r"""
NULLIF ¦ NULLIF ¦ función que devuelve NULL si dos valores son iguales ¦ evitar dividir entre cero ¦ SELECT 10 / NULLIF(0, 0) AS seguro; ¦ devuelve NULL en lugar de un error ¦ olvidar que el resultado puede ser NULL
IFNULL ¦ IFNULL ¦ función que reemplaza NULL por otro valor ¦ mostrar 0 cuando no hay descuento ¦ SELECT IFNULL(NULL, 0) AS descuento; ¦ cambia NULL por 0 ¦ confundirla con NULLIF, que hace lo contrario
INSTR ¦ INSTR ¦ función que da la posición de un texto dentro de otro ¦ saber dónde está la arroba de un correo ¦ SELECT INSTR('ana@correo.com', '@') AS posicion; ¦ muestra la posición de la arroba ¦ olvidar que devuelve 0 si no lo encuentra
LTRIM y RTRIM ¦ LTRIM ¦ funciones que quitan espacios a un lado ¦ limpiar datos copiados con espacios ¦ SELECT '[' || LTRIM('  hola  ') || ']', '[' || RTRIM('  hola  ') || ']'; ¦ quita espacios a la izquierda y a la derecha ¦ usar TRIM cuando solo querías un lado
Funciones de fecha strftime ¦ strftime ¦ función que extrae partes de una fecha ¦ agrupar ventas por mes ¦ SELECT strftime('%Y-%m', '2026-12-24') AS mes, strftime('%w', '2026-12-24') AS dia_semana; ¦ saca el mes y el día de la semana ¦ guardar fechas en formatos distintos de AAAA-MM-DD
Sumar días a una fecha ¦ date( ¦ funciones para sumar o restar tiempo a fechas ¦ calcular la fecha de vencimiento ¦ SELECT date('2026-12-01', '+30 days') AS vence, date('now') AS hoy; ¦ suma 30 días a una fecha ¦ sumar números directamente al texto de la fecha
Diferencia entre fechas ¦ julianday ¦ forma de calcular los días entre dos fechas ¦ saber cuántos días tardó un envío ¦ SELECT julianday('2026-12-24') - julianday('2026-12-01') AS dias; ¦ calcula 23 días de diferencia ¦ restar las fechas como texto
ABS y potencias ¦ ABS ¦ funciones matemáticas como valor absoluto y redondeo ¦ calcular diferencias sin signo ¦ SELECT ABS(-15) AS absoluto, ROUND(7.456, 1) AS redondeado; ¦ quita el signo y redondea ¦ olvidar que la división entre enteros corta los decimales
División decimal ¦ 1.0 * ¦ truco para obtener decimales al dividir enteros ¦ calcular un porcentaje correcto ¦ SELECT 7 / 2 AS entero, 1.0 * 7 / 2 AS decimal; ¦ muestra 3 y 3.5 ¦ dividir enteros y perder los decimales
Conteos condicionales ¦ SUM(CASE ¦ contar filas que cumplen una condición dentro de un grupo ¦ contar ventas grandes y pequeñas en una sola consulta ¦ """ + _T + r"""SELECT ciudad, SUM(CASE WHEN total >= 80 THEN 1 ELSE 0 END) AS grandes FROM ventas GROUP BY ciudad; ¦ cuenta las ventas grandes por ciudad ¦ hacer una consulta distinta por cada condición
GROUP_CONCAT ¦ GROUP_CONCAT ¦ función que une los valores de un grupo en un texto ¦ listar los productos de cada pedido ¦ """ + _T + r"""SELECT ciudad, GROUP_CONCAT(total, ', ') AS totales FROM ventas GROUP BY ciudad; ¦ junta los totales de cada ciudad ¦ olvidar que en MySQL el separador se escribe con SEPARATOR
GROUP BY con varias columnas ¦ GROUP BY ciudad, ¦ agrupar por más de una columna a la vez ¦ ver ventas por ciudad y por mes ¦ """ + _T + r"""SELECT ciudad, strftime('%m', fecha) AS mes, SUM(total) FROM ventas GROUP BY ciudad, mes; ¦ suma por ciudad y mes ¦ seleccionar columnas que no están en el GROUP BY
ORDER BY varias columnas ¦ ORDER BY ciudad, ¦ ordenar por un criterio y desempatar con otro ¦ ordenar por ciudad y luego por total ¦ """ + _T + r"""SELECT * FROM ventas ORDER BY ciudad ASC, total DESC; ¦ ordena por ciudad y luego del mayor al menor ¦ creer que DESC aplica a todas las columnas
NULLS FIRST y LAST ¦ NULLS LAST ¦ opción que decide dónde van los NULL al ordenar ¦ dejar los productos sin precio al final ¦ SELECT x FROM (SELECT 3 AS x UNION ALL SELECT NULL UNION ALL SELECT 1) ORDER BY x NULLS LAST; ¦ ordena y deja el NULL al final ¦ olvidar que cada motor ordena los NULL distinto
LIKE con guion bajo ¦ _ ¦ comodín que representa exactamente un carácter ¦ buscar códigos de 3 letras que empiezan con A ¦ SELECT 'ABC' LIKE 'A__' AS tres, 'ABCD' LIKE 'A__' AS cuatro; ¦ acepta solo textos de tres caracteres ¦ confundirlo con %, que acepta cualquier cantidad
GLOB ¦ GLOB ¦ comparación de patrones que distingue mayúsculas ¦ buscar archivos con una extensión exacta ¦ SELECT 'foto.PNG' GLOB '*.png' AS minus, 'foto.png' GLOB '*.png' AS ok; ¦ distingue mayúsculas en el patrón ¦ esperar que se comporte igual que LIKE
Valores de tabla con VALUES ¦ VALUES ¦ forma de crear filas al vuelo sin tabla ¦ probar consultas con datos rápidos ¦ SELECT * FROM (VALUES (1, 'Ana'), (2, 'Luis')); ¦ crea una tabla temporal de dos filas ¦ olvidar los paréntesis de cada fila
INSERT OR REPLACE y UPSERT ¦ ON CONFLICT ¦ insertar o actualizar si la fila ya existe ¦ guardar la configuración sin duplicarla ¦ CREATE TABLE conf (clave TEXT PRIMARY KEY, valor TEXT);⏎INSERT INTO conf VALUES ('tema', 'claro');⏎INSERT INTO conf VALUES ('tema', 'oscuro') ON CONFLICT(clave) DO UPDATE SET valor = excluded.valor;⏎SELECT * FROM conf; ¦ actualiza el tema en vez de duplicarlo ¦ hacer SELECT y luego INSERT o UPDATE con riesgo de choques
RETURNING ¦ RETURNING ¦ cláusula que devuelve las filas insertadas o cambiadas ¦ obtener el id de un registro recién creado ¦ CREATE TABLE u (id INTEGER PRIMARY KEY, n TEXT);⏎INSERT INTO u (n) VALUES ('Ana') RETURNING id, n; ¦ devuelve el id generado ¦ hacer otra consulta para buscar el último id
AUTOINCREMENT y rowid ¦ INTEGER PRIMARY KEY ¦ forma de generar ids automáticos ¦ numerar los clientes sin escribir el id ¦ CREATE TABLE c (id INTEGER PRIMARY KEY, n TEXT);⏎INSERT INTO c (n) VALUES ('Ana'), ('Luis');⏎SELECT * FROM c; ¦ genera los ids 1 y 2 solos ¦ escribir los ids a mano y repetirlos
""")

E7 = filas(r"""
DENSE_RANK ¦ DENSE_RANK ¦ función de ventana que numera sin saltos en los empates ¦ dar puestos en un concurso con empates ¦ WITH t(n,p) AS (VALUES ('Ana',90),('Luis',90),('Bea',80))⏎SELECT n, p, DENSE_RANK() OVER (ORDER BY p DESC) AS puesto FROM t; ¦ da el puesto 1, 1 y 2 ¦ confundirla con RANK, que salta al puesto 3
NTILE ¦ NTILE ¦ función de ventana que reparte filas en grupos iguales ¦ dividir clientes en cuartiles ¦ WITH t(x) AS (VALUES (1),(2),(3),(4))⏎SELECT x, NTILE(2) OVER (ORDER BY x) AS grupo FROM t; ¦ reparte cuatro filas en dos grupos ¦ esperar grupos exactos cuando las filas no se dividen bien
LEAD ¦ LEAD ¦ función de ventana que lee el valor de la fila siguiente ¦ comparar cada mes con el siguiente ¦ WITH t(m,v) AS (VALUES (1,10),(2,15),(3,12))⏎SELECT m, v, LEAD(v) OVER (ORDER BY m) AS siguiente FROM t; ¦ muestra el valor del mes siguiente ¦ olvidar que la última fila tiene NULL
FIRST_VALUE y LAST_VALUE ¦ FIRST_VALUE ¦ funciones de ventana que leen el primer o último valor ¦ comparar cada venta con la primera del mes ¦ WITH t(x) AS (VALUES (5),(3),(8))⏎SELECT x, FIRST_VALUE(x) OVER (ORDER BY x) AS primero FROM t; ¦ muestra el primer valor en cada fila ¦ usar LAST_VALUE sin marco y obtener la fila actual
Marco de ventana ¦ ROWS BETWEEN ¦ parte de las filas que mira una función de ventana ¦ calcular un promedio móvil de 3 días ¦ WITH t(d,v) AS (VALUES (1,10),(2,20),(3,30),(4,40))⏎SELECT d, v, AVG(v) OVER (ORDER BY d ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS movil FROM t; ¦ promedia cada día con los dos anteriores ¦ olvidar ORDER BY dentro de OVER
Porcentaje del total ¦ SUM() OVER () ¦ comparar cada fila con el total sin agrupar ¦ ver qué porcentaje aporta cada ciudad ¦ """ + _T + r"""SELECT ciudad, total, ROUND(100.0 * total / SUM(total) OVER (), 1) AS pct FROM ventas; ¦ muestra el porcentaje de cada venta ¦ usar GROUP BY y perder el detalle de cada fila
Top N por grupo ¦ ROW_NUMBER() OVER (PARTITION BY ¦ obtener las mejores filas de cada grupo ¦ mostrar la venta más alta de cada ciudad ¦ """ + _T + r"""SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY ciudad ORDER BY total DESC) AS n FROM ventas) WHERE n = 1; ¦ deja la mejor venta por ciudad ¦ intentar usar la función de ventana directamente en WHERE
Duplicados con GROUP BY ¦ HAVING COUNT(*) > 1 ¦ consulta que encuentra registros repetidos ¦ detectar correos duplicados ¦ WITH t(correo) AS (VALUES ('a@x.co'),('b@x.co'),('a@x.co'))⏎SELECT correo, COUNT(*) FROM t GROUP BY correo HAVING COUNT(*) > 1; ¦ muestra el correo repetido ¦ borrar duplicados sin revisar primero cuáles son
FULL OUTER JOIN ¦ FULL JOIN ¦ unión que conserva las filas de ambas tablas ¦ comparar dos listas y ver qué falta en cada una ¦ WITH a(x) AS (VALUES (1),(2)), b(x) AS (VALUES (2),(3))⏎SELECT a.x, b.x FROM a FULL JOIN b ON a.x = b.x; ¦ muestra coincidencias y lo que falta en cada lado ¦ olvidar que MySQL no la soporta y hay que usar UNION
JOIN con USING ¦ USING ¦ forma corta de unir tablas por una columna con el mismo nombre ¦ unir pedidos y clientes por id_cliente ¦ WITH c(id_cliente, n) AS (VALUES (1,'Ana')), p(id_cliente, total) AS (VALUES (1, 50))⏎SELECT * FROM c JOIN p USING (id_cliente); ¦ une por la columna común ¦ usar USING con columnas que tienen nombres distintos
JOIN con condiciones extra ¦ ON ... AND ¦ unir tablas filtrando dentro de la condición ¦ mostrar todos los clientes y solo sus pedidos grandes ¦ WITH c(id,n) AS (VALUES (1,'Ana'),(2,'Luis')), p(c,total) AS (VALUES (1,20),(1,90))⏎SELECT c.n, p.total FROM c LEFT JOIN p ON p.c = c.id AND p.total > 50; ¦ conserva a Luis y filtra los pedidos ¦ poner el filtro en WHERE y convertir el LEFT JOIN en INNER
Subconsulta escalar ¦ (SELECT ¦ subconsulta que devuelve un solo valor ¦ comparar cada venta con el promedio ¦ """ + _T + r"""SELECT id, total, total - (SELECT AVG(total) FROM ventas) AS diferencia FROM ventas; ¦ muestra cuánto se aleja cada venta del promedio ¦ escribir una subconsulta que devuelve varias filas
ANY y ALL ¦ > ALL ¦ comparar un valor con todos o alguno de una lista ¦ encontrar ventas mayores que todas las de Cali ¦ """ + _T + r"""SELECT * FROM ventas WHERE total > (SELECT MAX(total) FROM ventas WHERE ciudad = 'Cali'); ¦ muestra ventas mayores que las de Cali ¦ olvidar que SQLite no tiene ALL y hay que usar MAX
UPDATE con JOIN ¦ UPDATE ... FROM ¦ actualizar una tabla con datos de otra ¦ subir precios según su categoría ¦ CREATE TABLE p (id INT, cat TEXT, precio REAL); INSERT INTO p VALUES (1,'A',10);⏎CREATE TABLE ajuste (cat TEXT, pct REAL); INSERT INTO ajuste VALUES ('A',0.1);⏎UPDATE p SET precio = precio * (1 + ajuste.pct) FROM ajuste WHERE ajuste.cat = p.cat;⏎SELECT * FROM p; ¦ sube un 10 % los productos de la categoría A ¦ olvidar la condición y actualizar todas las filas
DELETE con subconsulta ¦ DELETE FROM ... WHERE id IN ¦ borrar filas que cumplen una condición en otra tabla ¦ borrar clientes sin pedidos ¦ CREATE TABLE c (id INT); INSERT INTO c VALUES (1),(2);⏎CREATE TABLE ped (c INT); INSERT INTO ped VALUES (1);⏎DELETE FROM c WHERE id NOT IN (SELECT c FROM ped);⏎SELECT * FROM c; ¦ borra el cliente que no tiene pedidos ¦ usar NOT IN con una subconsulta que puede tener NULL
Columnas generadas ¦ GENERATED ALWAYS ¦ columnas que se calculan solas a partir de otras ¦ guardar el total con IVA sin calcularlo cada vez ¦ CREATE TABLE f (base REAL, total REAL GENERATED ALWAYS AS (base * 1.19));⏎INSERT INTO f (base) VALUES (100);⏎SELECT * FROM f; ¦ calcula el total con IVA automáticamente ¦ intentar insertar un valor en la columna generada
Tablas temporales ¦ CREATE TEMP TABLE ¦ tablas que se borran al cerrar la conexión ¦ guardar resultados intermedios de un reporte ¦ CREATE TEMP TABLE resumen AS SELECT 1 AS mes, 500 AS total;⏎SELECT * FROM resumen; ¦ crea una tabla temporal con un resumen ¦ esperar que la tabla siga ahí al reconectar
Triggers en SQL ¦ CREATE TRIGGER ¦ acciones automáticas cuando cambian los datos ¦ guardar un historial de cambios ¦ CREATE TABLE prod (n TEXT, precio REAL); CREATE TABLE log (msg TEXT);⏎CREATE TRIGGER t AFTER UPDATE ON prod BEGIN INSERT INTO log VALUES (old.n || ': ' || old.precio || ' → ' || new.precio); END;⏎INSERT INTO prod VALUES ('Café', 5); UPDATE prod SET precio = 6;⏎SELECT * FROM log; ¦ registra el cambio de precio ¦ escribir triggers que disparan otros triggers sin control
Índices parciales y por expresión ¦ CREATE INDEX ... WHERE ¦ índices que cubren solo algunas filas o un cálculo ¦ acelerar búsquedas de pedidos pendientes ¦ CREATE TABLE ped (id INT, estado TEXT, correo TEXT);⏎CREATE INDEX idx_pend ON ped(id) WHERE estado = 'pendiente';⏎CREATE INDEX idx_correo ON ped(lower(correo));⏎SELECT name FROM sqlite_master WHERE type = 'index'; ¦ crea un índice parcial y otro por expresión ¦ crear índices en todas las columnas y hacer lentas las escrituras
JSON en SQL ¦ json_extract ¦ funciones para leer datos JSON guardados en una columna ¦ consultar preferencias guardadas como JSON ¦ SELECT json_extract('{"tema":"oscuro","nivel":3}', '$.tema') AS tema; ¦ lee el campo tema del JSON ¦ guardar todo en JSON y perder las ventajas de las columnas
""")

